 "content": "from collections import deque


def transform(grid):
    """Reverse the color order of nested nonzero layers in each object."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] != 0 and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            colors = {grid[y][x] for y, x in cells}
            boxes = {}
            for color in colors:
                pts = [(y, x) for y, x in cells if grid[y][x] == color]
                minr = min(y for y, _ in pts)
                maxr = max(y for y, _ in pts)
                minc = min(x for _, x in pts)
                maxc = max(x for _, x in pts)
                boxes[color] = ((maxr - minr + 1) * (maxc - minc + 1),
                                maxr - minr + 1, maxc - minc + 1)
            layers = sorted(colors, key=lambda color: boxes[color], reverse=True)
            mapping = dict(zip(layers, reversed(layers)))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
